package cn.mop.api;
import cn.mop.domain.*;
import cn.mop.domain.contact.*;
import cn.mop.domain.contact.CustomerContact.*;
import cn.mop.domain.contact.CustomerContactRepository.*;
import cn.mop.domain.worklog.ManualWorklog;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.databind.*;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.context.annotation.Profile;
import org.springframework.http.MediaType;
import org.springframework.web.bind.annotation.*;
import java.security.MessageDigest;
import java.time.Instant;
import java.util.*;
import static cn.mop.api.ApiResponse.*;

/** Current-tenant contact administration only. No channel verification, identity grant, dispatch or permanent delete. */
@RestController @RequestMapping("/api/v1/contacts") @Profile("remote_test")
public final class CustomerContactController {
    static final int MAX_BODY_BYTES=16384;
    private static final long MAX_VERSION=9007199254740991L;
    private static final Set<String> FIELDS=Set.of("expected_version","name","roles","mobile","email","wecom_user_id","preferred_priorities","quiet_window","enabled");
    private static final ObjectMapper INPUT=new ObjectMapper(JsonFactory.builder().enable(StreamReadFeature.STRICT_DUPLICATE_DETECTION).streamReadConstraints(StreamReadConstraints.builder().maxNestingDepth(3).maxStringLength(2048).maxNumberLength(16).build()).build()).enable(DeserializationFeature.FAIL_ON_TRAILING_TOKENS);
    private final PlatformRepository platform;private final CustomerContactRepository contacts;
    public CustomerContactController(PlatformRepository platform,CustomerContactRepository contacts){this.platform=platform;this.contacts=contacts;}
    @GetMapping Object list(HttpServletRequest request){Access a=access(request,false);var q=query(request,Set.of("name_query","view","page_size","before_created_at","before_id"));int size=pageSize(q);if(q.containsKey("before_created_at")!=q.containsKey("before_id"))throw invalid();Instant before=q.containsKey("before_created_at")?ManualWorklog.parseInstant(q.get("before_created_at")):null;String id=q.containsKey("before_id")?uuid(q.get("before_id")):null;View view;try{view=View.valueOf(q.getOrDefault("view","CURRENT"));}catch(IllegalArgumentException error){throw invalid();}var rows=contacts.list(a,q.getOrDefault("name_query",""),view,size+1,before,id);boolean more=rows.size()>size;var items=rows.subList(0,Math.min(size,rows.size()));Entry last=more?items.get(items.size()-1):null;return success(map("tenant_id",a.tenantId(),"items",items.stream().map(CustomerContactController::dto).toList(),"has_more",more,"next_before_created_at",last==null?null:last.createdAt().toString(),"next_before_id",last==null?null:last.id(),"view",view.name(),"source","postgresql","scope","CURRENT_TENANT","page_size_limit",100),request);}
    @GetMapping("/{id}") Object get(@PathVariable String id,HttpServletRequest request){Access a=access(request,false);query(request,Set.of());return success(dto(contacts.get(a,uuid(id))),request);}
    @GetMapping("/{id}/history") Object history(@PathVariable String id,HttpServletRequest request){Access a=access(request,false);var q=query(request,Set.of("page_size","before_version"));int size=pageSize(q);Long before=q.containsKey("before_version")?version(q.get("before_version")):null;String record=uuid(id);var rows=contacts.history(a,record,size+1,before);boolean more=rows.size()>size;var items=rows.subList(0,Math.min(size,rows.size()));return success(map("tenant_id",a.tenantId(),"contact_id",record,"items",items.stream().map(CustomerContactController::revisionDto).toList(),"has_more",more,"next_before_version",more?items.get(items.size()-1).version():null,"source","postgresql","scope","CURRENT_TENANT","page_size_limit",100),request);}
    @PostMapping(consumes=MediaType.APPLICATION_JSON_VALUE) Object create(HttpServletRequest request){access(request,true);return write(null,"CREATE",body(request),request);}
    @PatchMapping(value="/{id}",consumes=MediaType.APPLICATION_JSON_VALUE) Object update(@PathVariable String id,HttpServletRequest request){access(request,true);return write(uuid(id),"UPDATE",body(request),request);}
    @PostMapping(value="/{id}/archive",consumes=MediaType.APPLICATION_JSON_VALUE) Object archive(@PathVariable String id,HttpServletRequest request){access(request,true);return write(uuid(id),"ARCHIVE",body(request),request);}
    @PostMapping(value="/{id}/restore",consumes=MediaType.APPLICATION_JSON_VALUE) Object restore(@PathVariable String id,HttpServletRequest request){access(request,true);return write(uuid(id),"RESTORE",body(request),request);}
    Object write(String id,String action,JsonNode input,HttpServletRequest request){Access a=access(request,true);query(request,Set.of());if(!Set.of("CREATE","UPDATE","ARCHIVE","RESTORE").contains(action)||(id==null)!=action.equals("CREATE"))throw invalid();String record=id==null?null:uuid(id);fields(input,action.equals("ARCHIVE")?Set.of("expected_version"):FIELDS);JsonNode v=input.get("expected_version");if(!v.isIntegralNumber()||!v.canConvertToLong())throw invalid();long expected=v.longValue();if(action.equals("CREATE")?expected!=0:expected<1||expected>=MAX_VERSION)throw invalid();CustomerContact facts=action.equals("ARCHIVE")?null:facts(input);String key=request.getHeader("Idempotency-Key");if(key==null||!key.matches("[A-Za-z0-9._:-]{1,128}"))throw invalid();Object result=platform.idempotentAuthorized(a.actorId(),a.tenantId(),request.getMethod()+" "+route(request),key,hash(input),a.permissionVersion(),()->contacts.authorizeWrite(a,record),()->dto(switch(action){case "CREATE"->contacts.create(a,0,facts);case "UPDATE"->contacts.update(a,record,expected,facts);case "ARCHIVE"->contacts.archive(a,record,expected);case "RESTORE"->contacts.restore(a,record,expected,facts);default->throw invalid();}));return success(result,request);}
    private static CustomerContact facts(JsonNode input){Set<Role> roles=values(input.get("roles"),Role.class,false,3);Set<Priority> priorities=values(input.get("preferred_priorities"),Priority.class,true,4);QuietWindow quiet=null;JsonNode q=input.get("quiet_window");if(!q.isNull()){fields(q,Set.of("enabled","start","end"));JsonNode enabled=q.get("enabled");if(!enabled.isNull()&&!enabled.isBoolean())throw invalid();String start=nullableText(q.get("start")),end=nullableText(q.get("end"));quiet=new QuietWindow(enabled.isNull()?null:enabled.booleanValue(),start==null?null:QuietWindow.parseMinute(start),end==null?null:QuietWindow.parseMinute(end));}if(!input.get("enabled").isBoolean())throw invalid();return new CustomerContact(text(input.get("name")),roles,nullableText(input.get("mobile")),nullableText(input.get("email")),nullableText(input.get("wecom_user_id")),priorities,quiet,input.get("enabled").booleanValue());}
    private static <E extends Enum<E>> Set<E> values(JsonNode node,Class<E> type,boolean nullable,int limit){if(node.isNull()){if(nullable)return null;throw invalid();}if(!node.isArray()||node.size()>limit)throw invalid();Set<E> values=EnumSet.noneOf(type);for(var value:node){if(!value.isTextual())throw invalid();try{if(!values.add(Enum.valueOf(type,value.textValue())))throw invalid();}catch(IllegalArgumentException error){throw invalid();}}return values;}
    static Map<String,Object> dto(Entry row){var result=map("id",row.id(),"tenant_id",row.tenantId(),"created_by",row.createdBy(),"version",row.version(),"created_at",row.createdAt().toString(),"updated_at",row.updatedAt().toString(),"recorded_by",row.recordedBy(),"recorded_at",row.recordedAt().toString(),"action",row.action(),"archived",row.archived());result.putAll(factsDto(row.facts()));return result;}
    static Map<String,Object> revisionDto(Revision row){var result=map("version",row.version(),"previous_version",row.previousVersion(),"recorded_by",row.recordedBy(),"recorded_at",row.recordedAt().toString(),"action",row.action(),"archived",row.archived());result.putAll(factsDto(row.facts()));return result;}
    private static Map<String,Object> factsDto(CustomerContact facts){var quiet=facts.quietWindow();return map("name",facts.name(),"roles",facts.roles().stream().map(Enum::name).sorted().toList(),"mobile",facts.mobile(),"email",facts.email(),"wecom_user_id",facts.wecomUserId(),"preferred_priorities",facts.preferredPriorities()==null?null:facts.preferredPriorities().stream().map(Enum::name).sorted().toList(),"quiet_window",quiet==null?null:map("enabled",quiet.enabled(),"start",quiet.start()==null?null:quiet.start().toString(),"end",quiet.end()==null?null:quiet.end().toString()),"enabled",facts.enabled(),"quiet_timezone",CustomerContact.DISPLAY_ZONE,"contact_verification",facts.contactVerification(),"channel_verification",facts.channelVerification(),"notification_routing_status",facts.notificationRoutingStatus(),"delivery_eligible",facts.deliveryEligible(),"identity_binding_created",false,"notification_dispatched",false,"source","postgresql","record_source","SELF_REPORTED_CONTACT");}
    private Access access(HttpServletRequest request,boolean write){if(request.getUserPrincipal()==null||request.getSession(false)==null)throw expired();Object value=request.getSession(false).getAttribute("mop.tenant_id");if(!(value instanceof String tenant)||tenant.isBlank())throw expired();String actor=request.getUserPrincipal().getName();Membership member=platform.membership(actor,tenant).orElseThrow(CustomerContactController::expired);if(!member.active()||member.permissionVersion()<1)throw expired();if(!Capabilities.forRole(member.role()).contains(write?"contacts:write":"contacts:read"))throw new DomainException(403,"ACTION_FORBIDDEN","仅当前授权租户管理员和平台管理员可维护联系人");return new Access(actor,tenant,member.permissionVersion(),trace(request));}
    static JsonNode body(HttpServletRequest request){try{if(request.getContentLengthLong()>MAX_BODY_BYTES)throw invalid();byte[] bytes=request.getInputStream().readNBytes(MAX_BODY_BYTES+1);if(bytes.length>MAX_BODY_BYTES)throw invalid();try(var p=INPUT.getFactory().createParser(bytes)){int tokens=0;while(p.nextToken()!=null)if(++tokens>64)throw invalid();}return INPUT.readTree(bytes);}catch(Exception failure){throw invalid();}}
    private static Map<String,String> query(HttpServletRequest request,Set<String> allowed){var result=new HashMap<String,String>();request.getParameterMap().forEach((key,values)->{if(!allowed.contains(key)||values.length!=1||values[0]==null||values[0].codePointCount(0,values[0].length())>(key.equals("name_query")?200:64))throw invalid();result.put(key,values[0]);});return result;}
    private static int pageSize(Map<String,String> query){String value=query.getOrDefault("page_size","15");if(!Set.of("10","15","25","50","100").contains(value))throw invalid();return Integer.parseInt(value);}
    private static long version(String value){if(!value.matches("[1-9][0-9]{0,15}"))throw invalid();try{long v=Long.parseLong(value);if(v>MAX_VERSION)throw invalid();return v;}catch(NumberFormatException failure){throw invalid();}}
    private static void fields(JsonNode value,Set<String> fields){if(value==null||!value.isObject()||value.size()!=fields.size())throw invalid();value.fieldNames().forEachRemaining(k->{if(!fields.contains(k))throw invalid();});}
    private static String text(JsonNode value){if(value==null||!value.isTextual())throw invalid();return value.textValue();}
    private static String nullableText(JsonNode value){return value.isNull()?null:text(value);}
    private static String uuid(String value){if(value==null||!value.matches("[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}"))throw invalid();return UUID.fromString(value).toString();}
    private static JsonNode canonical(JsonNode node){if(!node.isObject())return node;var result=INPUT.createObjectNode();var names=new TreeSet<String>();node.fieldNames().forEachRemaining(names::add);for(String key:names){JsonNode value=node.get(key);if(Set.of("roles","preferred_priorities").contains(key)&&value.isArray()){var sorted=INPUT.createArrayNode();var entries=new TreeSet<String>();value.forEach(v->entries.add(v.textValue()));entries.forEach(sorted::add);result.set(key,sorted);}else result.set(key,canonical(value));}return result;}
    private static String hash(JsonNode input){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(INPUT.writeValueAsBytes(canonical(input))));}catch(Exception failure){throw new IllegalStateException("Contact request hash unavailable");}}
    private static DomainException invalid(){return new DomainException(400,"VALIDATION_ERROR","联系人字段、版本、集合或分页边界无效；未知字段保持显式null，不接受租户/核验/通知覆盖");}
    private static DomainException expired(){return new DomainException(401,"SESSION_EXPIRED","当前会话或成员关系已失效");}
}
